begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('d1000000-0000-0000-0000-000000000001','closure-owner@test.invalid'),('d1000000-0000-0000-0000-000000000002','closure-admin@test.invalid'),('d1000000-0000-0000-0000-000000000003','closure-staff@test.invalid');
insert into public.tenants(id,name,slug)values('d2000000-0000-0000-0000-000000000001','Closure business','closure-business'),('d2000000-0000-0000-0000-000000000002','Other closure business','other-closure-business');
insert into public.tenant_memberships(tenant_id,user_id,role)values('d2000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001','owner'),('d2000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000002','admin'),('d2000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000003','member');
insert into public.subscriptions(tenant_id,plan_id,status)select 'd2000000-0000-0000-0000-000000000001',id,'active'from public.plans where key='starter';
insert into public.properties(id,tenant_id,name,property_type)values('d3000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','Closing Hotel','hotel'),('d3000000-0000-0000-0000-000000000002','d2000000-0000-0000-0000-000000000001','Remaining Hotel','hotel'),('d3000000-0000-0000-0000-000000000003','d2000000-0000-0000-0000-000000000002','Other Hotel','hotel');
insert into public.property_memberships(property_id,tenant_id,user_id)values('d3000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000003');
insert into public.guests(id,tenant_id,full_name,phone)values('d4000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','Closure Guest','+919111111111');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)values('d5000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d3000000-0000-0000-0000-000000000001','d4000000-0000-0000-0000-000000000001','confirmed',current_date,current_date+2,100,'INR');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('d6000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d3000000-0000-0000-0000-000000000001','closure-phone','closure-waba','+919999999999','closure-ref');
insert into private.whatsapp_credentials(property_id,credentials_ref,ciphertext)values('d3000000-0000-0000-0000-000000000001','closure-ref','synthetic');
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id,last_inbound_at)values('d7000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d3000000-0000-0000-0000-000000000001','d6000000-0000-0000-0000-000000000001','919111111111',now());
insert into public.messages(id,tenant_id,property_id,conversation_id,direction,type,body,status)values('d8000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d3000000-0000-0000-0000-000000000001','d7000000-0000-0000-0000-000000000001','out','text','Test only','queued');
insert into public.whatsapp_guest_menu(property_id,data,enabled)values('d3000000-0000-0000-0000-000000000001','{}',true);
insert into public.whatsapp_campaigns(id,tenant_id,property_id,name,body,filters,selection_mode,status)values('d9000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d3000000-0000-0000-0000-000000000001','Closure campaign','Test only','{}','all','scheduled');
create function pg_temp.change_hotel(archive boolean default true)returns void language sql as $$select public.set_property_archived('d3000000-0000-0000-0000-000000000001',(select version from public.properties where id='d3000000-0000-0000-0000-000000000001'),archive,'Closing Hotel','Hotel closure test',true)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((public.property_lifecycle_context('d3000000-0000-0000-0000-000000000001')->>'can_change')::boolean,false,'Business admin can review but only owner can close');
select throws_ok($$select pg_temp.change_hotel()$$,'42501',null,'Business admin cannot close hotel');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.property_lifecycle_context('d3000000-0000-0000-0000-000000000003')$$,'42501',null,'Cannot review another business hotel');
select throws_ok($$select public.set_property_archived('d3000000-0000-0000-0000-000000000001',1,true,'Wrong hotel','Valid closure reason',true)$$,'22023',null,'Exact hotel name required');
select throws_ok($$select public.set_property_archived('d3000000-0000-0000-0000-000000000001',1,true,'Closing Hotel','Valid closure reason',false)$$,'22023',null,'External sales confirmation required');
select throws_ok($$select pg_temp.change_hotel()$$,'55000',null,'Confirmed stay blocks closure');
select set_config('test.closure_token',public.create_guest_portal_link('d5000000-0000-0000-0000-000000000001'),true);
reset role;
update public.reservations set status='cancelled'where id='d5000000-0000-0000-0000-000000000001';
insert into public.orders(id,tenant_id,property_id,kind)values('da000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','d3000000-0000-0000-0000-000000000001','restaurant');
set local role authenticated;
select throws_ok($$select pg_temp.change_hotel()$$,'55000',null,'Unfinished order blocks closure');
reset role;
update public.orders set status='served'where id='da000000-0000-0000-0000-000000000001';
update public.messages set status='sending',locked_at=now(),attempts=1 where id='d8000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.change_hotel()$$,'55000',null,'In-flight message blocks closure');
reset role;
update public.messages set status='queued',locked_at=null where id='d8000000-0000-0000-0000-000000000001';
set local role authenticated;
select lives_ok($$select pg_temp.change_hotel()$$,'Owner closes resolved hotel');
select ok((select archived_at is not null from public.properties where id='d3000000-0000-0000-0000-000000000001'),'Closure state saved');
select ok((select archived_at is null from public.properties where id='d3000000-0000-0000-0000-000000000002'),'Other hotel remains active');
select is((select count(*)::int from public.reservations where property_id='d3000000-0000-0000-0000-000000000001'),1,'Owner retains booking history');
select ok(private.has_permission('d3000000-0000-0000-0000-000000000001','finance.read'),'Owner retains financial reading');
select lives_ok($$select public.reservation_workspace('d3000000-0000-0000-0000-000000000001')$$,'Archived booking workspace remains readable');
select lives_ok($$select public.billing_workspace('d3000000-0000-0000-0000-000000000001')$$,'Archived billing workspace remains readable');
select lives_ok($$select public.hotel_report('d3000000-0000-0000-0000-000000000001')$$,'Archived hotel reports remain readable');
select ok(not private.has_permission('d3000000-0000-0000-0000-000000000001','reservations.manage'),'Archived hotel grants no operational management');
select throws_ok($$update public.properties set name='Edited archived hotel'where id='d3000000-0000-0000-0000-000000000001'$$,'55000',null,'Archived hotel settings immutable even for owner');
select throws_ok($$update public.properties set archived_at=null where id='d3000000-0000-0000-0000-000000000001'$$,'42501',null,'Direct table updates cannot reopen hotel');
select is_empty($$delete from public.properties where id='d3000000-0000-0000-0000-000000000002' returning id$$,'Direct API cannot cascade-delete hotel history');
select lives_ok($$select public.create_property('d2000000-0000-0000-0000-000000000001','db000000-0000-0000-0000-000000000001','Replacement Hotel','hotel','UTC','INR')$$,'Archiving frees active property capacity');
select throws_ok($$select pg_temp.change_hotel(false)$$,'53400',null,'Reopening cannot exceed plan capacity');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select is_empty($$select id from public.properties where id='d3000000-0000-0000-0000-000000000001'$$,'Ordinary assigned staff no longer see archived hotel');
reset role;
select is((select status from public.whatsapp_connections where id='d6000000-0000-0000-0000-000000000001'),'disabled','Hotel WhatsApp connection disabled');
select throws_ok($$update public.whatsapp_connections set status='active' where id='d6000000-0000-0000-0000-000000000001'$$,'55000',null,'Background process cannot reactivate archived sender');
select is((select count(*)::int from private.whatsapp_credentials where property_id='d3000000-0000-0000-0000-000000000001'),0,'Managed WhatsApp credential removed');
select is((select status from public.messages where id='d8000000-0000-0000-0000-000000000001'),'failed','Queued guest message cancelled');
select is((select status from public.whatsapp_campaigns where id='d9000000-0000-0000-0000-000000000001'),'cancelled','Scheduled campaign cancelled');
select ok((select not enabled from public.whatsapp_guest_menu where property_id='d3000000-0000-0000-0000-000000000001'),'Automatic guest menu disabled');
select ok(private.inbox_delivery_error('d8000000-0000-0000-0000-000000000001')is not null,'Outbound guard rejects archived hotel');
select throws_ok($$update public.reservations set total_amount=999 where id='d5000000-0000-0000-0000-000000000001'$$,'55000',null,'Background writes cannot mutate archived reservations');
select is((select count(*)::int from private.property_lifecycle_events where property_id='d3000000-0000-0000-0000-000000000001'),1,'Closure recorded once with actor and reason');
set local role anon;
select throws_ok($$select public.portal_command(current_setting('test.closure_token'),null,'consent_status')$$,'28000',null,'Closed hotel guest link revoked');
select throws_ok($$select public.property_lifecycle_context('d3000000-0000-0000-0000-000000000001')$$,'42501',null,'Anonymous callers cannot inspect closure context');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.set_property_archived((select id from public.properties where creation_request_id='db000000-0000-0000-0000-000000000001'),1,true,'Replacement Hotel','Free slot for reopening',true);
select lives_ok($$select pg_temp.change_hotel(false)$$,'Owner can reopen within plan capacity');
select throws_ok($$select public.set_property_archived('d3000000-0000-0000-0000-000000000001',1,true,'Closing Hotel','Stale request',true)$$,'40001',null,'Stale lifecycle command cannot override latest state');
reset role;
select is((select status from public.whatsapp_connections where id='d6000000-0000-0000-0000-000000000001'),'disabled','Reopening does not silently reconnect sender');
select is((select status from public.whatsapp_campaigns where id='d9000000-0000-0000-0000-000000000001'),'cancelled','Reopening does not revive campaigns');
select lives_ok($$update public.reservations set total_amount=101 where id='d5000000-0000-0000-0000-000000000001'$$,'Reopened records accept operations again');
select *from finish();
rollback;
